/bin/bash -lc "python3 - << 'PY'
import pandas as pd, re
df=pd.read_excel('mixed_units_register.xlsx', sheet_name='Disbursement Register', header=None)
data=df.iloc[6:]
def parse_amount(v):
    if pd.isna(v):
        return 0
    s=str(v).strip()
    if s in ('','-','NA','NaN','Amount'):
        return 0
    s=s.replace('₹','').replace(',','').strip()
    low=s.lower()
    m=re.match(r'"'^(['"\\d\\.]+)\\s*lakh"'$'"', low)
    if m:
        return float(m.group(1))*100000
    m=re.match(r'"'^(['"\\d\\.]+)\\s*l"'$'"', low)
    if m:
        return float(m.group(1))*100000
    m=re.match(r'"'^(['"\\d\\.]+)\\s*cr"'$'"', low)
    if m:
        return float(m.group(1))*10000000
    m=re.match(r'"'^(['"\\d\\.]+)\\s*k"'$'"', low)
    if m:
        return float(m.group(1))*1000
    # try numeric
    try:
        if re.fullmatch(r'[\\d\\.]+', s):
            return float(s)
        return 0
    except:
        return 0

total=0
count=0
for i,row in data.iterrows():
    rec=row[0]
    if not isinstance(rec,str) or not re.match(r'"'^MU-'"\\d{4}"'$'"', str(rec)):
        continue
    amt=parse_amount(row[5])
    total+=amt
    count+=1
print('rows',count)
print('total',total)
PY"
